import { motion } from "framer-motion";
import { ArrowUpRight, Zap, ShieldCheck, Gauge } from "lucide-react";
import LatencyGlobe from "./LatencyGlobe";

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  show: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.8, delay: i * 0.1, ease: [0.16, 1, 0.3, 1] },
  }),
};

export default function Hero() {
  return (
    <section id="top" className="relative pt-40 pb-24 px-6">
      <div className="mx-auto max-w-6xl grid lg:grid-cols-[1.05fr_0.95fr] gap-16 items-center">
        <div>
          <motion.div
            custom={0}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="inline-flex items-center gap-2 rounded-full glass px-4 py-1.5 text-xs font-mono-tag text-violet-300 mb-7"
          >
            <span className="relative flex h-1.5 w-1.5">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-violet-400 opacity-75" />
              <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-violet-400" />
            </span>
            LIVE IN SINGAPORE · SGP-1 DATACENTER
          </motion.div>

          <motion.h1
            custom={1}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="text-[3.1rem] sm:text-[3.8rem] leading-[1.03] font-semibold tracking-tight text-white"
          >
            A Singapore VPS
            <br />
            built for{" "}
            <span className="text-gradient">Asia-Pacific</span>
            <span className="text-gradient">.</span>
          </motion.h1>

          <motion.p
            custom={2}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-6 max-w-lg text-lg text-white/60 leading-relaxed"
          >
            Serve users across Southeast Asia, India, Australia, and East Asia
            from a Singapore datacenter — full-root NVMe servers with a
            dedicated IP and always-on DDoS, from{" "}
            <span className="text-white font-medium">$6.49/mo</span>.
          </motion.p>

          <motion.div
            custom={3}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-9 flex flex-wrap items-center gap-4"
          >
            <a href="#pricing" className="btn-primary">
              Deploy now <ArrowUpRight size={16} />
            </a>
            <a href="#pricing" className="btn-ghost">
              See pricing
            </a>
          </motion.div>

          <motion.div
            custom={4}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-14 grid grid-cols-3 gap-6 max-w-md"
          >
            {[
              { icon: Zap, label: "Median deploy", value: "47s" },
              { icon: Gauge, label: "NVMe on ZFS", value: "RAID-mirrored" },
              { icon: ShieldCheck, label: "DDoS protection", value: "Always-on" },
            ].map((s) => (
              <div key={s.label}>
                <s.icon size={16} className="text-violet-400 mb-2" />
                <div className="text-white font-semibold text-sm leading-tight">{s.value}</div>
                <div className="text-white/40 text-xs mt-0.5">{s.label}</div>
              </div>
            ))}
          </motion.div>
        </div>

        <motion.div
          initial={{ opacity: 0, scale: 0.92 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 1, delay: 0.3, ease: [0.16, 1, 0.3, 1] }}
          className="relative"
        >
          <LatencyGlobe />
        </motion.div>
      </div>
    </section>
  );
}

