import { motion } from "framer-motion";

const NODES = [
  { name: "Jakarta", ms: 12, x: 44, y: 74 },
  { name: "Manila", ms: 18, x: 74, y: 40 },
  { name: "Mumbai", ms: 41, x: 8, y: 32 },
  { name: "Sydney", ms: 52, x: 88, y: 88 },
  { name: "Tokyo", ms: 46, x: 84, y: 12 },
  { name: "Seoul", ms: 49, x: 66, y: 8 },
];

const CENTER = { x: 50, y: 52 };

export default function LatencyGlobe() {
  return (
    <div className="relative mx-auto aspect-square w-full max-w-[520px]">
      <div className="absolute inset-0 rounded-full bg-gradient-to-br from-indigo-500/20 via-violet-500/10 to-transparent blur-2xl" />

      <div className="glass-strong relative h-full w-full rounded-[2rem] p-6 overflow-hidden">
        <div className="absolute inset-0 opacity-40">
          {[...Array(4)].map((_, i) => (
            <div
              key={i}
              className="absolute rounded-full border border-violet-400/20"
              style={{
                inset: `${i * 12}%`,
              }}
            />
          ))}
        </div>

        <svg viewBox="0 0 100 100" className="absolute inset-0 h-full w-full">
          {NODES.map((n, i) => (
            <motion.line
              key={n.name}
              x1={CENTER.x}
              y1={CENTER.y}
              x2={n.x}
              y2={n.y}
              stroke="url(#lineGrad)"
              strokeWidth="0.35"
              strokeDasharray="2 2"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ pathLength: 1, opacity: 0.7 }}
              transition={{ duration: 1.2, delay: 0.5 + i * 0.12, ease: "easeOut" }}
            />
          ))}
          <defs>
            <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#a78bfa" />
              <stop offset="100%" stopColor="#22d3ee" />
            </linearGradient>
          </defs>

          {NODES.map((n, i) => (
            <motion.circle
              key={`pulse-${n.name}`}
              cx={n.x}
              cy={n.y}
              r="1.4"
              fill="#a78bfa"
              initial={{ opacity: 0 }}
              animate={{ opacity: [0, 0.5, 0] , r: [1.4, 3.2, 1.4]}}
              transition={{ duration: 2.4, repeat: Infinity, delay: i * 0.3, ease: "easeInOut" }}
            />
          ))}
        </svg>

        {NODES.map((n, i) => (
          <motion.div
            key={n.name}
            initial={{ opacity: 0, scale: 0.6 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.6, delay: 0.9 + i * 0.12 }}
            className="absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center"
            style={{ left: `${n.x}%`, top: `${n.y}%` }}
          >
            <span className="h-2 w-2 rounded-full bg-white shadow-[0_0_10px_rgba(255,255,255,0.8)]" />
            <span className="mt-1.5 whitespace-nowrap rounded-md bg-black/40 backdrop-blur px-1.5 py-0.5 text-[10px] font-mono-tag text-white/80 border border-white/10">
              {n.name} · {n.ms}ms
            </span>
          </motion.div>
        ))}

        <motion.div
          initial={{ opacity: 0, scale: 0.5 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.7, delay: 0.2, type: "spring" }}
          className="absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center z-10"
          style={{ left: `${CENTER.x}%`, top: `${CENTER.y}%` }}
        >
          <div className="relative flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-indigo-500 via-violet-500 to-fuchsia-500 shadow-[0_0_35px_rgba(139,92,246,0.7)]">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-2xl bg-violet-400 opacity-20" />
            <span className="text-white text-[11px] font-bold font-mono-tag">SGP</span>
          </div>
          <span className="mt-2 rounded-md bg-white/10 px-2 py-0.5 text-[10px] font-mono-tag text-white border border-white/10">
            Your server
          </span>
        </motion.div>
      </div>
    </div>
  );
}

