import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Plus } from "lucide-react";
import SectionHeading from "./SectionHeading";

const ITEMS = [
  {
    q: "Where exactly are the servers located?",
    a: "Every plan on this page deploys to our SGP-1 datacenter in Singapore, one of the region's best-connected network hubs on the APAC submarine cable routes.",
  },
  {
    q: "Who benefits most from a Singapore VPS?",
    a: "Anyone with users in Southeast Asia, India, Australia, or East Asia. If your traffic currently crosses the Pacific to a US datacenter, moving to Singapore is the single biggest latency win available.",
  },
  {
    q: "Will latency be good to Australia and India too?",
    a: "Yes — Singapore's position on regional cable routes keeps round-trips low to Sydney, Mumbai, and most major APAC population centres, not just Southeast Asia.",
  },
  {
    q: "Do Singapore plans include the same features?",
    a: "Every tier runs the same full-root NVMe platform with a dedicated IPv4, always-on DDoS protection, and daily backups — you're only choosing vCPU, RAM, and storage.",
  },
  {
    q: "Can I host a game server in Singapore?",
    a: "Absolutely. Low, consistent latency is exactly what real-time multiplayer needs — Standard and Pro plans are popular choices for small-to-mid game servers.",
  },
];

export default function FAQ() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  return (
    <section id="faq" className="relative py-28 px-6">
      <SectionHeading eyebrow="FAQ" title="Questions, answered" />

      <div className="mx-auto max-w-3xl mt-14 space-y-3">
        {ITEMS.map((item, i) => {
          const isOpen = openIndex === i;
          return (
            <motion.div
              key={item.q}
              initial={{ opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-40px" }}
              transition={{ duration: 0.5, delay: i * 0.05 }}
              className="glass rounded-2xl overflow-hidden"
            >
              <button
                onClick={() => setOpenIndex(isOpen ? null : i)}
                className="w-full flex items-center justify-between gap-4 px-6 py-5 text-left"
              >
                <span className="text-white font-medium text-[15px]">{item.q}</span>
                <motion.span
                  animate={{ rotate: isOpen ? 45 : 0 }}
                  transition={{ duration: 0.3 }}
                  className="shrink-0 flex h-7 w-7 items-center justify-center rounded-full bg-white/8 text-violet-300"
                >
                  <Plus size={15} />
                </motion.span>
              </button>
              <AnimatePresence initial={false}>
                {isOpen && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.35, ease: [0.16, 1, 0.3, 1] }}
                    className="overflow-hidden"
                  >
                    <p className="px-6 pb-5 text-white/55 text-sm leading-relaxed">{item.a}</p>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>
    </section>
  );
}

