import { motion } from "framer-motion";
import { ArrowRight } from "lucide-react";
import DeployTerminal from "./DeployTerminal";

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  show: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, delay: i * 0.08, ease: [0.16, 1, 0.3, 1] },
  }),
};

export default function Hero() {
  return (
    <section id="top" className="relative pt-36 pb-24 px-6">
      <div className="mx-auto max-w-6xl grid lg:grid-cols-[1fr_0.85fr] gap-16 items-start">
        <div className="lg:pt-6">
          <motion.div
            custom={0}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mono text-xs text-white/40 mb-5"
          >
            SGP-1 · SINGAPORE
          </motion.div>

          <motion.h1
            custom={1}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="text-[2.75rem] sm:text-[3.4rem] leading-[1.06] font-semibold tracking-tight text-white"
          >
            A Singapore VPS built
            <br />
            for Asia-Pacific
          </motion.h1>

          <motion.p
            custom={2}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-6 max-w-md text-[1.05rem] text-white/50 leading-relaxed"
          >
            Serve users across Southeast Asia, India, Australia, and East
            Asia from a Singapore datacenter — full-root NVMe, a dedicated
            IP, and DDoS protection, from $6.49/mo.
          </motion.p>

          <motion.div
            custom={3}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-8 flex flex-wrap items-center gap-3"
          >
            <a href="#pricing" className="btn-primary">
              Deploy now <ArrowRight size={15} />
            </a>
            <a href="#pricing" className="btn-ghost">
              See pricing
            </a>
          </motion.div>

          <motion.div
            custom={4}
            initial="hidden"
            animate="show"
            variants={fadeUp}
            className="mt-12 grid grid-cols-3 gap-6 max-w-md border-t hairline pt-6"
          >
            {[
              { value: "47s", label: "median deploy" },
              { value: "99.9%", label: "network uptime" },
              { value: "24/7", label: "DDoS mitigation" },
            ].map((s) => (
              <div key={s.label}>
                <div className="text-white font-semibold text-lg">{s.value}</div>
                <div className="text-white/35 text-xs mt-1">{s.label}</div>
              </div>
            ))}
          </motion.div>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7, delay: 0.2, ease: [0.16, 1, 0.3, 1] }}
        >
          <DeployTerminal />
        </motion.div>
      </div>
    </section>
  );
}

