import { useEffect, useState } from "react";
import { Menu, X } from "lucide-react";

const LINKS = [
  { label: "Why Singapore", href: "#why" },
  { label: "How it works", href: "#how" },
  { label: "Plans", href: "#pricing" },
  { label: "FAQ", href: "#faq" },
];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 inset-x-0 z-50 transition-colors duration-300 ${
        scrolled ? "bg-[#08090d]/85 backdrop-blur border-b hairline" : "border-b border-transparent"
      }`}
    >
      <div className="mx-auto max-w-6xl flex items-center justify-between px-6 py-4">
        <a href="#top" className="flex items-center gap-2">
          <span className="flex h-5 w-5 items-center justify-center rounded bg-[var(--accent)]">
            <span className="h-1.5 w-1.5 rounded-sm bg-white" />
          </span>
          <span className="text-[0.95rem] font-semibold text-white">Nxeon</span>
        </a>

        <nav className="hidden md:flex items-center gap-8">
          {LINKS.map((l) => (
            <a key={l.href} href={l.href} className="text-sm text-white/55 hover:text-white transition-colors">
              {l.label}
            </a>
          ))}
        </nav>

        <div className="hidden md:flex items-center gap-2">
          <a href="#" className="text-sm text-white/55 hover:text-white transition-colors px-3 py-2">
            Sign in
          </a>
          <a href="#pricing" className="btn-primary !py-2 !px-4 !text-sm">
            Deploy now
          </a>
        </div>

        <button className="md:hidden text-white/70" onClick={() => setOpen((v) => !v)} aria-label="Toggle menu">
          {open ? <X size={20} /> : <Menu size={20} />}
        </button>
      </div>

      {open && (
        <div className="md:hidden border-t hairline px-6 py-5 flex flex-col gap-4 bg-[#08090d]">
          {LINKS.map((l) => (
            <a key={l.href} href={l.href} onClick={() => setOpen(false)} className="text-white/70 text-sm">
              {l.label}
            </a>
          ))}
          <a href="#pricing" onClick={() => setOpen(false)} className="btn-primary justify-center !text-sm">
            Deploy now
          </a>
        </div>
      )}
    </header>
  );
}

