const nav = document.querySelector('nav, header');
const btn = document.querySelector('a[class*="btn"], button');
const logo = document.querySelector('header img, header svg, a[href="/"] img, a[href="/"] svg');
const getFonts = () => Array.from(document.querySelectorAll('*')).slice(0,50).map(e=>getComputedStyle(e).fontFamily);
JSON.stringify({
  bodyBg: body.backgroundColor,
  bodyColor: body.color,
  bodyFont: body.fontFamily,
  h1Text: h1 ? h1.textContent.slice(0,80) : null,
  h1Font: h1 ? getComputedStyle(h1).fontFamily : null,
  h1Color: h1 ? getComputedStyle(h1).color : null,
  h1Size: h1 ? getComputedStyle(h1).fontSize : null,
  h1Weight: h1 ? getComputedStyle(h1).fontWeight : null,
  btnBg: btn ? getComputedStyle(btn).backgroundColor : null,
  btnBgImage: btn ? getComputedStyle(btn).backgroundImage.slice(0,150) : null,
  logoExists: !!logo,
  logoOuterHTML: logo ? logo.outerHTML.slice(0,300) : null,
}, null, 2)

function uniq(arr){return [...new Set(arr)]}
