const bgImages = uniq(all.map(e=>getComputedStyle(e).backgroundImage).filter(v=>v && v!=='none' && v.includes('gradient')));
const bgColors = uniq(all.map(e=>getComputedStyle(e).backgroundColor).filter(v=>v && v!=='rgba(0, 0, 0, 0)'));
const textColors = uniq(all.map(e=>getComputedStyle(e).color));
JSON.stringify({
  gradients: bgImages.slice(0,15),
  bgColors: bgColors.slice(0,25),
}, null, 2)

const btns = Array.from(document.querySelectorAll('a,button')).filter(b=>/deploy|get started|start|sign up|create/i.test(b.textContent||''));
