input.content:
@import "tailwindcss";

@font-face {
  font-family: "Geist";
  src: url("/fonts/Geist-Variable.woff2") format("woff2-variations"), url("/fonts/Geist-Variable.woff2") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #060a14;
  --ink-raised: #0a0e1c;
  --ink-panel: #0d1224;
  --line: rgba(255, 255, 255, 0.08);
  --line-strong: rgba(255, 255, 255, 0.16);
  --text: #e9ebf5;
  --text-dim: #8a90ab;
  --text-faint: #565c78;

  --blue: #3b82f6;
  --violet: #6f47f5;
  --cyan: #22d3ee;

  --grad-brand: linear-gradient(90deg, var(--blue) 0%, var(--violet) 100%);
  --grad-brand-wide: linear-gradient(110deg, var(--violet), var(--blue), var(--cyan), var(--violet));
  --glow-blue: rgba(59, 130, 246, 0.16);
  --glow-violet: rgba(111, 71, 245, 0.18);

  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font-family: "Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

#root {
  min-height: 100svh;
  position: relative;
}

::selection {
  background: rgba(111, 71, 245, 0.35);
  color: #fff;
}

::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: var(--ink);
}
::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-radius: 8px;
}

h1, h2, h3, h4 {
  font-family: "Geist", ui-sans-serif, system-ui, sans-serif;
  letter-spacing: -0.03em;
  color: #ffffff;
  margin: 0;
  font-weight: 700;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
}

.mono {
  font-family: ui-monospace, "SF Mono", Consolas, monospace;
}

/* ---------- primitives ---------- */

.panel {
  background: var(--ink-raised);
  border: 1px solid var(--line);
}

.panel-hover {
  transition: border-color 0.3s ease, background 0.3s ease;
}
.panel-hover:hover {
  border-color: var(--line-strong);
  background: var(--ink-panel);
}

.text-gradient {
  background: var(--grad-brand);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hairline {
  border-color: var(--line);
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.35rem;
  border-radius: 9999px;
  font-weight: 600;
  font-size: 0.9rem;
  color: #fff;
  background: var(--grad-brand-wide);
  background-size: 300% 100%;
  background-position: 0% 50%;
  box-shadow: 0 8px 24px -8px rgba(111, 71, 245, 0.55);
  transition: background-position 0.6s ease, transform 0.2s ease, box-shadow 0.2s ease;
}
.btn-primary:hover {
  background-position: 100% 50%;
  transform: translateY(-1px);
  box-shadow: 0 10px 30px -6px rgba(111, 71, 245, 0.7);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.35rem;
  border-radius: 9999px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text);
  border: 1px solid var(--line-strong);
  background: rgba(255, 255, 255, 0.02);
  transition: border-color 0.2s ease, background 0.2s ease;
}
.btn-ghost:hover {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
}

.grid-overlay {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse 70% 55% at 50% 0%, black 25%, transparent 85%);
}

.blink {
  animation: blink 1s step-end infinite;
}
@keyframes blink {
  50% { opacity: 0; }
}

