import { useEffect, useRef, useState } from "react";
import { motion } from "framer-motion";
import { Check } from "lucide-react";

const NODES = [
  { name: "Jakarta", ms: 12, angle: -90 },
  { name: "Manila", ms: 18, angle: -18 },
  { name: "Mumbai", ms: 41, angle: 54 },
  { name: "Tokyo", ms: 46, angle: 126 },
  { name: "Sydney", ms: 52, angle: 198 },
];

const FRAGMENTS = Array.from({ length: 8 }, (_, i) => {
  const angle = (i * 45 * Math.PI) / 180;
  const radius = i % 2 === 0 ? 150 : 128;
  return {
    x: Math.cos(angle) * radius,
    y: Math.sin(angle) * radius,
    delay: i * 0.05,
    size: i % 3 === 0 ? 14 : 9,
  };
});

const NODE_RADIUS = 168;
const CORE = 200; // svg/box center in a 400x400 stage

function polar(angleDeg: number, radius: number) {
  const a = (angleDeg * Math.PI) / 180;
  return { x: CORE + Math.cos(a) * radius, y: CORE + Math.sin(a) * radius };
}

export default function SignalCore() {
  const [count, setCount] = useState(47);
  const [live, setLive] = useState(false);
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;

    const tick = setInterval(() => {
      setCount((c) => {
        const next = c - (3 + Math.floor(Math.random() * 4));
        if (next <= 0) {
          clearInterval(tick);
          return 0;
        }
        return next;
      });
    }, 90);

    const liveTimer = setTimeout(() => setLive(true), 1450);

    return () => {
      clearInterval(tick);
      clearTimeout(liveTimer);
    };
  }, []);

  return (
    <div className="relative mx-auto aspect-square w-full max-w-[480px]">
      <svg viewBox="0 0 400 400" className="absolute inset-0 h-full w-full overflow-visible">
        <defs>
          <linearGradient id="beamGrad" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="var(--violet)" />
            <stop offset="100%" stopColor="var(--cyan)" />
          </linearGradient>
          <radialGradient id="ringGrad">
            <stop offset="0%" stopColor="var(--violet)" stopOpacity="0.9" />
            <stop offset="100%" stopColor="var(--blue)" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* radar rings */}
        {live &&
          [0, 1, 2].map((i) => (
            <motion.circle
              key={i}
              cx={CORE}
              cy={CORE}
              r={44}
              fill="none"
              stroke="url(#beamGrad)"
              strokeWidth="1"
              style={{ transformOrigin: `${CORE}px ${CORE}px` }}
              initial={{ opacity: 0, scale: 0.6 }}
              animate={{ opacity: [0, 0.5, 0], scale: [0.6, 2.6, 2.6] }}
              transition={{ duration: 2.8, repeat: Infinity, delay: i * 0.9, ease: "easeOut" }}
            />
          ))}

        {/* beams to nodes */}
        {NODES.map((n, i) => {
          const p = polar(n.angle, NODE_RADIUS);
          return (
            <motion.line
              key={n.name}
              x1={CORE}
              y1={CORE}
              x2={p.x}
              y2={p.y}
              stroke="url(#beamGrad)"
              strokeWidth="1"
              strokeDasharray="3 3"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={live ? { pathLength: 1, opacity: 0.55 } : {}}
              transition={{ duration: 0.9, delay: 0.15 + i * 0.12, ease: "easeOut" }}
            />
          );
        })}

        {/* node dots */}
        {NODES.map((n, i) => {
          const p = polar(n.angle, NODE_RADIUS);
          return (
            <motion.circle
              key={`dot-${n.name}`}
              cx={p.x}
              cy={p.y}
              r={4}
              fill="#fff"
              initial={{ opacity: 0, scale: 0 }}
              animate={live ? { opacity: 1, scale: 1 } : {}}
              transition={{ duration: 0.4, delay: 0.5 + i * 0.12, ease: "backOut" }}
            />
          );
        })}
        {live &&
          NODES.map((n, i) => {
            const p = polar(n.angle, NODE_RADIUS);
            return (
              <motion.circle
                key={`ping-${n.name}`}
                cx={p.x}
                cy={p.y}
                r={4}
                fill="none"
                stroke="var(--cyan)"
                strokeWidth="1"
                style={{ transformOrigin: `${p.x}px ${p.y}px` }}
                initial={{ opacity: 0.6, scale: 1 }}
                animate={{ opacity: 0, scale: 3 }}
                transition={{ duration: 1.8, repeat: Infinity, delay: 1 + i * 0.3, ease: "easeOut" }}
              />
            );
          })}
      </svg>

      {/* fragments flying into the core */}
      {!live &&
        FRAGMENTS.map((f, i) => (
          <motion.div
            key={i}
            className="absolute left-1/2 top-1/2 rounded-sm"
            style={{
              width: f.size,
              height: f.size,
              background: "var(--grad-brand)",
              marginLeft: -f.size / 2,
              marginTop: -f.size / 2,
            }}
            initial={{ x: f.x, y: f.y, opacity: 1, rotate: 0 }}
            animate={{ x: 0, y: 0, opacity: 0, rotate: 90 }}
            transition={{ duration: 1.1, delay: f.delay, ease: [0.5, 0, 0.4, 1] }}
          />
        ))}

      {/* core */}
      <motion.div
        className="absolute left-1/2 top-1/2 flex flex-col items-center justify-center rounded-2xl"
        style={{
          width: 84,
          height: 84,
          marginLeft: -42,
          marginTop: -42,
          background: live ? "var(--grad-brand)" : "var(--ink-panel)",
          border: live ? "none" : "1px solid var(--line-strong)",
        }}
        animate={{
          boxShadow: live
            ? "0 0 50px -6px rgba(111,71,245,0.65)"
            : "0 0 0px rgba(111,71,245,0)",
        }}
        transition={{ duration: 0.6 }}
      >
        {!live ? (
          <span className="mono text-white text-xl font-semibold tabular-nums">{count}</span>
        ) : (
          <motion.div
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ duration: 0.4, ease: "backOut" }}
            className="flex flex-col items-center"
          >
            <Check size={20} className="text-white" strokeWidth={2.5} />
            <span className="mono text-white text-[10px] font-semibold mt-1 tracking-wider">LIVE</span>
          </motion.div>
        )}
      </motion.div>

      {/* labels */}
      {NODES.map((n, i) => {
        const p = polar(n.angle, NODE_RADIUS);
        const leftPct = (p.x / 400) * 100;
        const topPct = (p.y / 400) * 100;
        return (
          <motion.div
            key={`label-${n.name}`}
            className="absolute -translate-x-1/2 flex flex-col items-center"
            style={{
              left: `${leftPct}%`,
              top: `${topPct}%`,
              marginTop: n.angle === -90 ? -30 : 10,
            }}
            initial={{ opacity: 0, y: 4 }}
            animate={live ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.4, delay: 0.7 + i * 0.12 }}
          >
            <span className="mono whitespace-nowrap rounded-md border border-[var(--line)] bg-[var(--ink-raised)] px-2 py-1 text-[10px] text-white/70">
              {n.name} <span className="text-white/40">·</span> <span className="text-white">{n.ms}ms</span>
            </span>
          </motion.div>
        );
      })}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { motion } from "framer-motion";
import { Check } from "lucide-react";

const NODES = [
  { name: "Jakarta", ms: 12, angle: -90 },
  { name: "Manila", ms: 18, angle: -18 },
  { name: "Mumbai", ms: 41, angle: 54 },
  { name: "Tokyo", ms: 46, angle: 126 },
  { name: "Sydney", ms: 52, angle: 198 },
];

const FRAGMENTS = Array.from({ length: 8 }, (_, i) => {
  const angle = (i * 45 * Math.PI) / 180;
  const radius = i % 2 === 0 ? 150 : 128;
  return {
    x: Math.cos(angle) * radius,
    y: Math.sin(angle) * radius,
    delay: i * 0.05,
    size: i % 3 === 0 ? 14 : 9,
  };
});

const NODE_RADIUS = 168;
const CORE = 200; // svg/box center in a 400x400 stage

function polar(angleDeg: number, radius: number) {
  const a = (angleDeg * Math.PI) / 180;
  return { x: CORE + Math.cos(a) * radius, y: CORE + Math.sin(a) * radius };
}

export default function SignalCore() {
  const [count, setCount] = useState(47);
  const [live, setLive] = useState(false);

  useEffect(() => {
    setCount(47);
    setLive(false);

    const tick = setInterval(() => {
      setCount((c) => {
        const next = c - (3 + Math.floor(Math.random() * 4));
        if (next <= 0) {
          clearInterval(tick);
          return 0;
        }
        return next;
      });
    }, 90);

    const liveTimer = setTimeout(() => setLive(true), 1450);

    return () => {
      clearInterval(tick);
      clearTimeout(liveTimer);
    };
  }, []);

  return (
    <div className="relative mx-auto aspect-square w-full max-w-[480px]">
      <svg viewBox="0 0 400 400" className="absolute inset-0 h-full w-full overflow-visible">
        <defs>
          <linearGradient id="beamGrad" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="var(--violet)" />
            <stop offset="100%" stopColor="var(--cyan)" />
          </linearGradient>
          <radialGradient id="ringGrad">
            <stop offset="0%" stopColor="var(--violet)" stopOpacity="0.9" />
            <stop offset="100%" stopColor="var(--blue)" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* radar rings */}
        {live &&
          [0, 1, 2].map((i) => (
            <motion.circle
              key={i}
              cx={CORE}
              cy={CORE}
              r={44}
              fill="none"
              stroke="url(#beamGrad)"
              strokeWidth="1"
              style={{ transformOrigin: `${CORE}px ${CORE}px` }}
              initial={{ opacity: 0, scale: 0.6 }}
              animate={{ opacity: [0, 0.5, 0], scale: [0.6, 2.6, 2.6] }}
              transition={{ duration: 2.8, repeat: Infinity, delay: i * 0.9, ease: "easeOut" }}
            />
          ))}

        {/* beams to nodes */}
        {NODES.map((n, i) => {
          const p = polar(n.angle, NODE_RADIUS);
          return (
            <motion.line
              key={n.name}
              x1={CORE}
              y1={CORE}
              x2={p.x}
              y2={p.y}
              stroke="url(#beamGrad)"
              strokeWidth="1"
              strokeDasharray="3 3"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={live ? { pathLength: 1, opacity: 0.55 } : {}}
              transition={{ duration: 0.9, delay: 0.15 + i * 0.12, ease: "easeOut" }}
            />
          );
        })}

        {/* node dots */}
        {NODES.map((n, i) => {
          const p = polar(n.angle, NODE_RADIUS);
          return (
            <motion.circle
              key={`dot-${n.name}`}
              cx={p.x}
              cy={p.y}
              r={4}
              fill="#fff"
              initial={{ opacity: 0, scale: 0 }}
              animate={live ? { opacity: 1, scale: 1 } : {}}
              transition={{ duration: 0.4, delay: 0.5 + i * 0.12, ease: "backOut" }}
            />
          );
        })}
        {live &&
          NODES.map((n, i) => {
            const p = polar(n.angle, NODE_RADIUS);
            return (
              <motion.circle
                key={`ping-${n.name}`}
                cx={p.x}
                cy={p.y}
                r={4}
                fill="none"
                stroke="var(--cyan)"
                strokeWidth="1"
                style={{ transformOrigin: `${p.x}px ${p.y}px` }}
                initial={{ opacity: 0.6, scale: 1 }}
                animate={{ opacity: 0, scale: 3 }}
                transition={{ duration: 1.8, repeat: Infinity, delay: 1 + i * 0.3, ease: "easeOut" }}
              />
            );
          })}
      </svg>

      {/* fragments flying into the core */}
      {!live &&
        FRAGMENTS.map((f, i) => (
          <motion.div
            key={i}
            className="absolute left-1/2 top-1/2 rounded-sm"
            style={{
              width: f.size,
              height: f.size,
              background: "var(--grad-brand)",
              marginLeft: -f.size / 2,
              marginTop: -f.size / 2,
            }}
            initial={{ x: f.x, y: f.y, opacity: 1, rotate: 0 }}
            animate={{ x: 0, y: 0, opacity: 0, rotate: 90 }}
            transition={{ duration: 1.1, delay: f.delay, ease: [0.5, 0, 0.4, 1] }}
          />
        ))}

      {/* core */}
      <motion.div
        className="absolute left-1/2 top-1/2 flex flex-col items-center justify-center rounded-2xl"
        style={{
          width: 84,
          height: 84,
          marginLeft: -42,
          marginTop: -42,
          background: live ? "var(--grad-brand)" : "var(--ink-panel)",
          border: live ? "none" : "1px solid var(--line-strong)",
        }}
        animate={{
          boxShadow: live
            ? "0 0 50px -6px rgba(111,71,245,0.65)"
            : "0 0 0px rgba(111,71,245,0)",
        }}
        transition={{ duration: 0.6 }}
      >
        {!live ? (
          <span className="mono text-white text-xl font-semibold tabular-nums">{count}</span>
        ) : (
          <motion.div
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ duration: 0.4, ease: "backOut" }}
            className="flex flex-col items-center"
          >
            <Check size={20} className="text-white" strokeWidth={2.5} />
            <span className="mono text-white text-[10px] font-semibold mt-1 tracking-wider">LIVE</span>
          </motion.div>
        )}
      </motion.div>

      {/* labels */}
      {NODES.map((n, i) => {
        const p = polar(n.angle, NODE_RADIUS);
        const leftPct = (p.x / 400) * 100;
        const topPct = (p.y / 400) * 100;
        return (
          <motion.div
            key={`label-${n.name}`}
            className="absolute -translate-x-1/2 flex flex-col items-center"
            style={{
              left: `${leftPct}%`,
              top: `${topPct}%`,
              marginTop: n.angle === -90 ? -30 : 10,
            }}
            initial={{ opacity: 0, y: 4 }}
            animate={live ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.4, delay: 0.7 + i * 0.12 }}
          >
            <span className="mono whitespace-nowrap rounded-md border border-[var(--line)] bg-[var(--ink-raised)] px-2 py-1 text-[10px] text-white/70">
              {n.name} <span className="text-white/40">·</span> <span className="text-white">{n.ms}ms</span>
            </span>
          </motion.div>
        );
      })}
    </div>
  );
}

